WITH observed AS (
  SELECT MIN(event_time) AS first_event, MAX(event_time) AS last_event FROM public.machine_event WHERE equipment_id=${focus_machine:sqlstring}
), bounds AS (
  SELECT GREATEST($__timeFrom()::timestamptz,first_event) AS from_ts, LEAST($__timeTo()::timestamptz,last_event) AS to_ts FROM observed
), seed AS (
  SELECT m.event_type,m.event_time,m.id FROM public.machine_event m CROSS JOIN bounds b
  WHERE m.equipment_id=${focus_machine:sqlstring} AND m.message_type='status' AND m.event_time<b.from_ts
  ORDER BY m.event_time DESC,m.id DESC LIMIT 1
), points AS (
  SELECT * FROM seed UNION ALL
  SELECT m.event_type,m.event_time,m.id FROM public.machine_event m CROSS JOIN bounds b
  WHERE m.equipment_id=${focus_machine:sqlstring} AND m.message_type='status' AND m.event_time>=b.from_ts AND m.event_time<=b.to_ts
), segments AS (
  SELECT event_type,GREATEST(event_time,from_ts) AS segment_start,LEAST(LEAD(event_time,1,to_ts) OVER (ORDER BY event_time,id),to_ts) AS segment_end
  FROM points CROSS JOIN bounds
), durations AS (
  SELECT event_type,GREATEST(EXTRACT(EPOCH FROM (segment_end-segment_start)),0) AS seconds FROM segments WHERE segment_end>segment_start
)
SELECT ROUND((100.0*COALESCE(SUM(seconds) FILTER (WHERE event_type='RUN'),0)/NULLIF(SUM(seconds),0))::NUMERIC,1) AS "Run Ratio %",
       COALESCE(SUM(seconds) FILTER (WHERE event_type='RUN'),0)::DOUBLE PRECISION AS "Run Time",
       COALESCE(SUM(seconds) FILTER (WHERE event_type='STOP'),0)::DOUBLE PRECISION AS "Stop Time"
FROM durations
